    def sum_of_digits(num):
        # Convert the number to a string to process each digit
        num_str = str(num)
        # Initialize the sum of digits
        digit_sum = 0
        # Iterate over each character in the string
        for i, char in enumerate(num_str):
            if i == 0 and char == '-':
                # If the first character is a negative sign, make the next digit negative
                continue
            elif i == 0 and char.isdigit():
                # If the first character is a digit, add it to the sum
                digit_sum += int(char)
            else:
                # For other digits, add or subtract based on the sign
                if num_str[i - 1] == '-':
                    digit_sum -= int(char)
                else:
                    digit_sum += int(char)
        return digit_sum

    # Count the numbers with a sum of digits greater than 0
    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1
    return count
