def is_sorted(lst):
    if len(lst) <= 1:
        return True

    duplicate_count = {}

    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            return False
        if lst[i] == lst[i - 1]:
            if lst[i] in duplicate_count:
                duplicate_count[lst[i]] += 1
            else:
                duplicate_count[lst[i]] = 2
            if duplicate_count[lst[i]] > 2:
                return False

    return True

# Test cases
